    { customerId: 'C-002', number: 'INV-2026-0002' },
    { customerId: 'C-001', number: 'INV-2026-0003' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-002', 'C-001');
  assert.equal(result.ok, true);

  const newCustomers = result.value.customers;
  const newInvoices = result.value.invoices;

  assert.equal(newCustomers.find(c => c.id === 'C-001').name, 'Northwind Studio');
