  const initialCount = customers.length;
  const result = mergeCustomers(customers, invoices, 'C-005', 'C-006');
  assert.equal(result.ok, true);

  assert.equal(result.value.customers.length, initialCount - 1);
  assert.equal(result.value.customers.find(c => c.id === 'C-005'), undefined);
